                                property.kind = definition.kind;
                                property.flags = definition.flags;
                                property.argumentCount = definition.argumentCount;
                                const auto &guard = document.Objects()[static_cast<std::size_t>(guardIndex)];
                                property.intValue = guard.oid;
                                // A guard instantiated as a PROXY root is found
                                // through the wrapper OID: CploFindSwObjects sees
                                // the matching PROXY and expands its PXR roots.
                                if (guard.proxyRecordIndex >= 0 &&
                                    static_cast<std::size_t>(guard.proxyRecordIndex) < document.Proxies().size())
                                {
                                    const auto proxyOwner =
                                        document.Proxies()[static_cast<std::size_t>(guard.proxyRecordIndex)]
                                            .ownerObjectIndex;
                                    if (proxyOwner >= 0 &&
                                        static_cast<std::size_t>(proxyOwner) < document.Objects().size() &&
                                        document.Objects()[static_cast<std::size_t>(proxyOwner)].oid >= 0)
                                        property.intValue =
                                            document.Objects()[static_cast<std::size_t>(proxyOwner)].oid;
                                }
