                                    if (createdObject.parentIndex >= 0)
                                        parentWorld = sceneRenderer.ResolvedObjectTransform(createdObject.parentIndex);
                                    const auto &first = createdShape->points.front();
                                    const auto &last = createdShape->points.back();
                                    const glm::vec3 midpoint =
                                        glm::vec3(parentWorld * glm::vec4((first[0] + last[0]) * 0.5f,
                                                                          (first[1] + last[1]) * 0.5f,
                                                                          (first[2] + last[2]) * 0.5f, 1.0f));
