                auto machineRecord =
                    std::find_if(document.EditableStateMachines().begin(), document.EditableStateMachines().end(),
                                 [&](const BrxSmRecord &candidate)
                                 { return candidate.ownerObjectIndex == request.machineObjectIndex; });
