                        return "Transform";
                    case InspectorPage::Appearance:
                        return "Appearance";
                    case InspectorPage::Animation:
                        return "Animation";
                    case InspectorPage::Lighting:
                        return "Lighting";
                    case InspectorPage::Model:
                        return "Model";
                    case InspectorPage::CollisionPhysics:
                        return "Collision & Physics";
                    case InspectorPage::Gameplay:
                        return "Behavior & Audio";
                    case InspectorPage::Relationships:
                        return "Relationships";
                    case InspectorPage::Specialized:
