                            {
                                ImGui::Text("Instance of source GLOB %d", glob.sourceGlobIndex);
                                if (ImGui::Button("Make unique"))
                                {
                                    glob.instanced = false;
                                    glob.sourceGlobIndex = -1;
                                    globChanged = true;
                                }
                                if (ImGui::TreeNode("Instance transform"))
                                {
                                    for (int row = 0; row < 4; ++row)
                                    {
                                        ImGui::PushID(row);
                                        globChanged |=
                                            ImGui::DragFloat4("##row", glob.instanceTransform + row * 4, 0.01f);
                                        ImGui::PopID();
                                    }
                                    ImGui::TextDisabled("Stored exactly as the BRX GLOB instance matrix.");
                                    ImGui::TreePop();
                                }
                            }
                            static constexpr const char *renderPhaseNames[] = {"Dynamic texture",
                                                                               "Background",
                                                                               "Blot context",
                                                                               "Opaque",
                                                                               "Cutout",
                                                                               "Cel border",
                                                                               "Projection volume",
                                                                               "Opaque after projection volume",
                                                                               "Cutout after projection volume",
                                                                               "Cel border after projection volume",
                                                                               "Murk clear",
                                                                               "Murk opaque",
                                                                               "Murk fill",
                                                                               "Translucent",
                                                                               "Translucent cel border",
                                                                               "Blip",
                                                                               "Foreground",
                                                                               "World map"};
                            int renderPhase = glob.renderPhase == 0xff ? -1 : glob.renderPhase;
