                    const auto referenceState = [&](const char *label, const std::int16_t oid)
                    {
                        if (oid == -1)
                        {
                            ImGui::TextDisabled("%s: none", label);
                            return;
                        }
                        const bool found =
                            std::any_of(document.Objects().begin(), document.Objects().end(),
                                        [&](const BrxObjectRecord &candidate) { return candidate.oid == oid; });
                        ImGui::TextColored(found ? ImVec4(0.30f, 0.85f, 0.48f, 1.0f) : ImVec4(1.0f, 0.40f, 0.25f, 1.0f),
                                           "%s: OID %d (%s)", label, oid, found ? "resolved" : "missing");
                    };
                    if ((alox.flags & 0x0cu) != 0)
                        referenceState("Rotation source", alox.rotationSourceOid);
                    if ((alox.flags & 0x10u) != 0)
                        referenceState("IK target", alox.ikTargetOid);
                    if ((alox.flags & 0x20u) != 0)
                        referenceState("Elbow", alox.elbowOid);
