                        if (hasOwnCelBorders)
                            drawAloSetting(95, "Cel color");
                        drawAloSetting(96, "Override cel color for hierarchy");
                        drawAloSetting(97, "Color-throb mode");
                        drawAloSetting(98, "Throb-in color");
                        drawAloSetting(99, "Throb-out color");
                        drawAloSetting(100, "Throb transition time");
