                            bindingRow("Right hand ALO", 0x36, 2);
                            bindingRow("Cane tool ALO", 0x16f, 2);
                            bindingRow("Cane hook ALO", 0x170, 2);
                            bindingRow("Primary physics SO", 0x64, 3);
                            const bool leftFoot = findRigObject(0x37, 2) >= 0 || findRigObject(0x38, 2) >= 0;
                            const bool rightFoot = findRigObject(0x3a, 2) >= 0 || findRigObject(0x3b, 2) >= 0;
                            ImGui::TextColored(
                                leftFoot ? ImVec4(0.30f, 0.85f, 0.48f, 1.0f) : ImVec4(1.0f, 0.40f, 0.25f, 1.0f),
                                "%s  Left foot ball/heel (OID 55 or 56)", leftFoot ? "FOUND" : "MISSING");
                            ImGui::TextColored(
                                rightFoot ? ImVec4(0.30f, 0.85f, 0.48f, 1.0f) : ImVec4(1.0f, 0.40f, 0.25f, 1.0f),
                                "%s  Right foot ball/heel (OID 58 or 59)", rightFoot ? "FOUND" : "MISSING");
                            ImGui::TextDisabled(
                                "PostJtLoad dereferences these bindings; a bare JT is not runtime-safe.");
                            ImGui::TreePop();
