                                const glm::mat4 inverseView = glm::inverse(camera.ViewMatrix());
                                warpPreviewSavedDirection = -glm::vec3(inverseView[2]);
                                if (glm::dot(warpPreviewSavedDirection, warpPreviewSavedDirection) < 0.000001f)
                                    warpPreviewSavedDirection = glm::vec3(1.0f, 0.0f, 0.0f);
