                                    continue;
                                random = random * 1664525u + 1013904223u;
                                float u = static_cast<float>(random & 0xffffu) / 65535.0f;
                                random = random * 1664525u + 1013904223u;
                                float v = static_cast<float>(random & 0xffffu) / 65535.0f;
