                    static std::unordered_map<std::int32_t, int> fragilePresetByOid;
                    static std::unordered_map<std::int32_t, int> fragileTestSourceByOid;
                    static std::unordered_map<std::int32_t, float> fragileTestSpeedByOid;
                    static std::unordered_map<std::int32_t, float> fragileTestMassByOid;
                    static std::unordered_map<std::int32_t, bool> fragileAdvancedByOid;
                    int &preset = fragilePresetByOid[selectedObjectIndex];
                    int &testSource = fragileTestSourceByOid[selectedObjectIndex];
                    float &testSpeed = fragileTestSpeedByOid[selectedObjectIndex];
                    float &testMass = fragileTestMassByOid[selectedObjectIndex];
                    bool &advanced = fragileAdvancedByOid[selectedObjectIndex];
                    if (testSpeed <= 0.0f)
                        testSpeed = 800.0f;
                    if (testMass <= 0.0f)
                        testMass = 100.0f;

