                        if (ImGui::SmallButton("Center"))
                            missilePreviewTargetOffset = glm::vec3(0.0f);
                        ImGui::SameLine();
                        if (ImGui::SmallButton("Top"))
                            missilePreviewTargetOffset = glm::vec3(0.0f, 0.0f, 100.0f);
                        ImGui::SameLine();
                        if (ImGui::SmallButton("Base"))
                            missilePreviewTargetOffset = glm::vec3(0.0f, 0.0f, -50.0f);
                        ImGui::DragFloat3("Preview target velocity", &missilePreviewTargetVelocity.x, 1.0f, -10000.0f,
                                          10000.0f, "%.1f units/s");
