                            break;
                        case 777:
                            values[0] = 5.0f;
                            break;
                        case 779:
                            values[0] = 0.0f;
                            break;
                        case 780:
                            values[0] = 8.0f;
                            break;
                        case 782:
                            values[0] = 1.0f;
