                                            event.lipsyncAnimationOid = -1;
                                        for (std::size_t candidateIndex = 0; candidateIndex < document.Objects().size();
                                             ++candidateIndex)
                                        {
                                            const auto &candidate = document.Objects()[candidateIndex];
                                            if (!CidDerivesFrom(candidate.cid, 131) ||
                                                candidate.parentIndex != selectedObjectIndex)
                                                continue;
                                            const std::string label = "ASEG OID " + std::to_string(candidate.oid) +
                                                                      "##dialogLipsync" +
                                                                      std::to_string(candidateIndex);
                                            if (ImGui::Selectable(label.c_str(),
                                                                  event.lipsyncAnimationOid == candidate.oid))
                                                event.lipsyncAnimationOid = candidate.oid;
                                        }
                                        ImGui::EndCombo();
