                                    drawOidPicker("Camera focus", event.focusOid, 2, "Use speaker");
                                    drawOidPicker("Anchor point", event.anchorPointOid, 126, "Use dialog default");
                                    if (oldSpeaker != event.speakerOid || oldLipsync != event.lipsyncAnimationOid ||
                                        oldFocus != event.focusOid || oldAnchor != event.anchorPointOid)
                                        event.modified = dialog.modified = true;
                                    char subtitle[1024]{};
