                        if (shapePreviewObject != selectedObjectIndex)
                        {
                            shapePreviewObject = selectedObjectIndex;
                            selectedShapePoint = 0;
                            shapePreviewParameter = 0.0f;
                            shapePreviewPlaying = false;
                        }
                        ImGui::BeginDisabled(object.proxyClone);
                        ImGui::SeparatorText("Viewport transform target");
                        if (ImGui::RadioButton("Selected point", !shapeGizmoWholeCurve))
                            shapeGizmoWholeCurve = false;
                        ImGui::SameLine();
                        if (ImGui::RadioButton("Whole curve", shapeGizmoWholeCurve))
                            shapeGizmoWholeCurve = true;
                        ImGui::TextDisabled(
                            shapeGizmoWholeCurve
                                ? "The W move gizmo offsets every control point together without changing the curve's shape."
                                : "The W move gizmo edits only the selected control point.");
                        ImGui::SeparatorText("Build curve from objects");
                        static int shapeObjectOrder = 0;
                        static bool shapeObjectsClosed = false;
                        const char *shapeObjectOrders[]{"Hierarchy order", "Nearest neighbor", "Around center (XY)"};
                        ImGui::Combo("Point order", &shapeObjectOrder, shapeObjectOrders,
                                     static_cast<int>(std::size(shapeObjectOrders)));
                        ImGui::SameLine();
                        ImGui::Checkbox("Close generated loop", &shapeObjectsClosed);
                        ImGui::TextDisabled(
                            "Object world origins become control points in the SHAPE parent's local coordinates.");
                        const auto replaceShapeFromObjects =
                            [&](std::vector<std::int32_t> sourceObjects, const char *sourceDescription)
                        {
                            sourceObjects.erase(std::remove_if(sourceObjects.begin(), sourceObjects.end(),
                                                               [&](const std::int32_t index)
                                                               {
                                                                   return index < 0 || index == selectedObjectIndex ||
                                                                          static_cast<std::size_t>(index) >=
                                                                              document.Objects().size();
                                                               }),
                                                sourceObjects.end());
                            std::sort(sourceObjects.begin(), sourceObjects.end());
                            sourceObjects.erase(std::unique(sourceObjects.begin(), sourceObjects.end()),
                                                sourceObjects.end());
                            const std::size_t maximumSources = shapeObjectsClosed ? 254u : 255u;
                            if (sourceObjects.size() < 2)
                            {
                                status = std::string(sourceDescription) +
                                         " needs at least two usable objects besides the SHAPE.";
                                return;
                            }
                            if (sourceObjects.size() > maximumSources)
                            {
                                status = "The generated SHAPE would exceed the retail 255-control-point limit.";
                                return;
                            }
                            glm::mat4 parentToWorld(1.0f);
                            if (object.parentIndex >= 0 &&
                                static_cast<std::size_t>(object.parentIndex) < document.Objects().size())
                                parentToWorld = sceneRenderer.ResolvedObjectTransform(object.parentIndex);
                            const float determinant = glm::determinant(parentToWorld);
                            if (!std::isfinite(determinant) || std::abs(determinant) <= 0.000001f)
                            {
                                status = "Cannot build this SHAPE because its parent has a singular world transform.";
                                return;
                            }
                            std::vector<glm::vec3> worldPoints;
                            worldPoints.reserve(sourceObjects.size());
                            for (const auto index : sourceObjects)
                                worldPoints.push_back(glm::vec3(sceneRenderer.ResolvedObjectTransform(index)[3]));
                            if (shapeObjectOrder == 1 && worldPoints.size() > 2)
                            {
                                for (std::size_t slot = 1; slot < worldPoints.size(); ++slot)
                                {
                                    std::size_t nearest = slot;
                                    float nearestDistance = (std::numeric_limits<float>::max)();
                                    for (std::size_t candidate = slot; candidate < worldPoints.size(); ++candidate)
                                    {
                                        const glm::vec3 delta = worldPoints[candidate] - worldPoints[slot - 1];
                                        const float distance = glm::dot(delta, delta);
                                        if (distance < nearestDistance)
                                        {
                                            nearestDistance = distance;
                                            nearest = candidate;
                                        }
                                    }
                                    std::swap(worldPoints[slot], worldPoints[nearest]);
                                    std::swap(sourceObjects[slot], sourceObjects[nearest]);
                                }
                            }
                            else if (shapeObjectOrder == 2 && worldPoints.size() > 2)
                            {
                                glm::vec3 center(0.0f);
                                for (const auto &point : worldPoints)
                                    center += point;
                                center /= static_cast<float>(worldPoints.size());
                                std::vector<std::size_t> order(worldPoints.size());
                                std::iota(order.begin(), order.end(), 0u);
                                std::stable_sort(order.begin(), order.end(),
                                                 [&](const std::size_t left, const std::size_t right)
                                                 {
                                                     const float a = std::atan2(worldPoints[left].y - center.y,
                                                                                worldPoints[left].x - center.x);
                                                     const float b = std::atan2(worldPoints[right].y - center.y,
                                                                                worldPoints[right].x - center.x);
                                                     return a < b;
                                                 });
                                auto originalPoints = worldPoints;
                                auto originalObjects = sourceObjects;
                                for (std::size_t index = 0; index < order.size(); ++index)
                                {
                                    worldPoints[index] = originalPoints[order[index]];
                                    sourceObjects[index] = originalObjects[order[index]];
                                }
                            }
                            for (std::size_t index = 1; index < worldPoints.size(); ++index)
                                if (glm::distance(worldPoints[index - 1], worldPoints[index]) <= 0.0001f)
                                {
                                    status =
                                        "Cannot rebuild SHAPE: two consecutive source objects occupy the same world position.";
                                    return;
                                }
                            if (shapeObjectsClosed && glm::distance(worldPoints.front(), worldPoints.back()) <= 0.0001f)
                            {
                                status =
                                    "Cannot close generated SHAPE: its first and last source objects occupy the same world position.";
                                return;
                            }
                            const glm::mat4 worldToParent = glm::inverse(parentToWorld);
                            shape.points.clear();
                            shape.parameters.clear();
                            shape.tangentsIn.clear();
                            shape.tangentsOut.clear();
                            shape.closed = false;
                            for (const auto &worldPoint : worldPoints)
                            {
                                const glm::vec3 local = glm::vec3(worldToParent * glm::vec4(worldPoint, 1.0f));
                                shape.points.push_back({local.x, local.y, local.z});
                                if (shape.parameters.empty())
                                    shape.parameters.push_back(0.0f);
                                else
                                {
                                    const auto &previous = shape.points[shape.points.size() - 2u];
                                    shape.parameters.push_back(
                                        shape.parameters.back() +
                                        glm::distance(local, glm::vec3(previous[0], previous[1], previous[2])));
                                }
                            }
                            if (shapeObjectsClosed)
                            {
                                const auto first = shape.points.front();
                                const auto &last = shape.points.back();
                                shape.parameters.push_back(shape.parameters.back() +
                                                           glm::distance(glm::vec3(last[0], last[1], last[2]),
                                                                         glm::vec3(first[0], first[1], first[2])));
                                shape.points.push_back(first);
                                shape.closed = true;
                            }
                            if (shape.hermite)
                            {
                                shape.tangentsIn.resize(shape.points.size());
                                shape.tangentsOut.resize(shape.points.size());
                                for (std::size_t index = 0; index < shape.points.size(); ++index)
                                {
                                    const std::size_t previous =
                                        index > 0 ? index - 1
                                                  : (shape.closed && shape.points.size() > 2 ? shape.points.size() - 2
                                                                                             : index);
                                    const std::size_t next =
                                        index + 1 < shape.points.size() ? index + 1 : (shape.closed ? 1u : index);
                                    const glm::vec3 before(shape.points[previous][0], shape.points[previous][1],
                                                           shape.points[previous][2]);
                                    const glm::vec3 after(shape.points[next][0], shape.points[next][1],
                                                          shape.points[next][2]);
                                    float span = std::abs(shape.parameters[next] - shape.parameters[previous]);
                                    if (shape.closed && index == 0 && shape.parameters.size() > 2)
                                        span =
                                            (shape.parameters.back() - shape.parameters[shape.parameters.size() - 2]) +
                                            (shape.parameters[1] - shape.parameters.front());
                                    const glm::vec3 tangent =
                                        span > 0.000001f ? (after - before) / span : glm::vec3(0.0f);
                                    shape.tangentsIn[index] = {tangent.x, tangent.y, tangent.z};
                                    shape.tangentsOut[index] = {tangent.x, tangent.y, tangent.z};
                                }
                                if (shape.closed)
                                {
                                    shape.tangentsIn.back() = shape.tangentsOut.front();
                                    shape.tangentsOut.back() = shape.tangentsOut.front();
                                }
                            }
                            selectedShapePoint = 0;
                            shapePreviewParameter = 0.0f;
                            status = "Rebuilt SHAPE from " + std::to_string(sourceObjects.size()) + " " +
                                     sourceDescription + " using parent-local coordinates.";
                        };
                        std::vector<std::int32_t> selectedShapeSources;
                        for (const auto index : sceneRenderer.SelectedObjectIndices())
                            if (index != selectedObjectIndex)
                                selectedShapeSources.push_back(index);
                        ImGui::BeginDisabled(selectedShapeSources.size() < 2);
                        if (ImGui::Button("Replace from selected objects"))
                            replaceShapeFromObjects(selectedShapeSources, "selected objects");
                        ImGui::EndDisabled();
                        ImGui::SameLine();
                        std::vector<std::int32_t> parentChildren;
                        if (object.parentIndex >= 0)
                            for (std::size_t index = 0; index < document.Objects().size(); ++index)
                                if (document.Objects()[index].parentIndex == object.parentIndex &&
                                    static_cast<std::int32_t>(index) != selectedObjectIndex)
                                    parentChildren.push_back(static_cast<std::int32_t>(index));
                        ImGui::BeginDisabled(parentChildren.size() < 2);
                        if (ImGui::Button("Replace from parent siblings"))
                            replaceShapeFromObjects(parentChildren, "sibling objects");
                        ImGui::EndDisabled();
                        if (selectedShapeSources.size() < 2)
                            ImGui::TextDisabled(
                                "Ctrl-select the SHAPE and at least two source objects to enable selected-object conversion.");
                        int kind = shape.hermite ? 1 : 0;
                        const char *kinds[]{"Linear", "Cubic Bezier/Hermite"};
                        if (ImGui::Combo("Curve interpolation", &kind, kinds, 2))
                        {
                            shape.hermite = kind == 1;
                            if (shape.hermite)
                            {
                                shape.tangentsIn.resize(shape.points.size());
                                shape.tangentsOut.resize(shape.points.size());
                                for (std::size_t pointIndex = 0; pointIndex < shape.points.size(); ++pointIndex)
                                {
                                    const std::size_t previous =
                                        pointIndex > 0
                                            ? pointIndex - 1
                                            : (shape.closed && shape.points.size() > 2 ? shape.points.size() - 2
                                                                                       : pointIndex);
                                    const std::size_t next = pointIndex + 1 < shape.points.size()
                                                                 ? pointIndex + 1
                                                                 : (shape.closed ? 0 : pointIndex);
                                    const glm::vec3 before(shape.points[previous][0], shape.points[previous][1],
                                                           shape.points[previous][2]);
                                    const glm::vec3 after(shape.points[next][0], shape.points[next][1],
                                                          shape.points[next][2]);
                                    float parameterSpan =
                                        previous < shape.parameters.size() && next < shape.parameters.size()
                                            ? std::abs(shape.parameters[next] - shape.parameters[previous])
                                            : 0.0f;
                                    if (shape.closed && pointIndex == 0 && shape.parameters.size() > 2)
                                        parameterSpan =
                                            (shape.parameters.back() - shape.parameters[shape.parameters.size() - 2]) +
                                            (shape.parameters[1] - shape.parameters.front());
                                    const glm::vec3 derivative =
                                        parameterSpan > 0.000001f ? (after - before) / parameterSpan : glm::vec3(0.0f);
                                    shape.tangentsIn[pointIndex] = {derivative.x, derivative.y, derivative.z};
                                    shape.tangentsOut[pointIndex] = {derivative.x, derivative.y, derivative.z};
                                }
                                if (shape.closed && shape.points.size() > 1)
                                {
                                    shape.tangentsIn.back() = shape.tangentsOut.front();
                                    shape.tangentsOut.back() = shape.tangentsOut.front();
                                }
                            }
                            else
                            {
                                shape.tangentsIn.clear();
                                shape.tangentsOut.clear();
                            }
                            status = "Changed SHAPE curve interpolation in memory.";
                        }
                        const bool parameterCountValid = shape.parameters.size() == shape.points.size();
                        ImGui::BeginDisabled(!parameterCountValid);
                        bool requestedClosed = shape.closed;
                        if (ImGui::Checkbox("Closed loop", &requestedClosed))
                        {
                            if (requestedClosed && !shape.closed)
                            {
                                if (shape.points.size() >= 255)
                                    status =
                                        "Cannot close this SHAPE: the explicit seam would exceed the 255-point BRX limit.";
                                else if (shape.points.size() < 2)
                                    status =
                                        "Cannot close this SHAPE until it has at least two distinct control points.";
                                else if (!shape.points.empty())
                                {
                                    shape.closed = true;
                                    shape.points.push_back(shape.points.front());
                                    const float span =
                                        shape.parameters.size() > 1
                                            ? (std::max)(shape.parameters.back() -
                                                             shape.parameters[shape.parameters.size() - 2],
                                                         0.0001f)
                                            : 1.0f;
                                    shape.parameters.push_back(
                                        (shape.parameters.empty() ? 0.0f : shape.parameters.back()) + span);
                                    if (shape.hermite)
                                    {
                                        shape.tangentsIn.push_back(shape.tangentsOut.empty()
                                                                       ? std::array<float, 3>{}
                                                                       : shape.tangentsOut.front());
                                        shape.tangentsOut.push_back(shape.tangentsOut.empty()
                                                                        ? std::array<float, 3>{}
                                                                        : shape.tangentsOut.front());
                                    }
                                    status = "Closed the SHAPE with ProjectCane's required explicit seam endpoint.";
                                }
                            }
                            else if (!requestedClosed && shape.closed)
                            {
                                shape.closed = false;
                                if (shape.points.size() > 2)
                                {
                                    const glm::vec3 first(shape.points.front()[0], shape.points.front()[1],
                                                          shape.points.front()[2]);
                                    const glm::vec3 last(shape.points.back()[0], shape.points.back()[1],
                                                         shape.points.back()[2]);
                                    if (glm::distance(first, last) <= 0.01f)
                                    {
                                        shape.points.pop_back();
                                        if (!shape.parameters.empty())
                                            shape.parameters.pop_back();
                                        if (!shape.tangentsIn.empty())
                                            shape.tangentsIn.pop_back();
                                        if (!shape.tangentsOut.empty())
                                            shape.tangentsOut.pop_back();
                                    }
                                }
                                status = "Opened the SHAPE and removed its duplicated seam endpoint.";
                            }
                        }
                        ImGui::EndDisabled();
                        ImGui::SameLine();
                        ImGui::TextDisabled("%zu control points", shape.points.size());
                        if (shape.parameters.size() != shape.points.size())
                        {
                            ImGui::TextColored(ImVec4(1.0f, 0.4f, 0.2f, 1.0f),
                                               "Parameter count mismatch: %zu parameters for %zu points.",
                                               shape.parameters.size(), shape.points.size());
                            if (ImGui::Button("Repair parameter array"))
                            {
                                shape.parameters.resize(shape.points.size());
                                for (std::size_t i = 0; i < shape.parameters.size(); ++i)
                                    shape.parameters[i] = static_cast<float>(i);
                                status = "Repaired the SHAPE parameter array with explicit uniform values.";
                            }
                        }
                        ImGui::BeginDisabled(!parameterCountValid);
                        const auto replaceParametersPreservingCurve = [&](std::vector<float> replacement)
                        {
                            if (replacement.size() != shape.parameters.size())
                                return;
                            if (shape.hermite && shape.tangentsIn.size() == shape.points.size() &&
                                shape.tangentsOut.size() == shape.points.size())
                            {
                                const auto old = shape.parameters;
                                for (std::size_t i = 0; i < shape.points.size(); ++i)
                                {
                                    if (i > 0)
                                    {
                                        const float oldSpan = old[i] - old[i - 1];
                                        const float newSpan = replacement[i] - replacement[i - 1];
                                        if (oldSpan > 0.000001f && newSpan > 0.000001f)
                                            for (float &component : shape.tangentsIn[i])
                                                component *= oldSpan / newSpan;
                                    }
                                    if (i + 1 < shape.points.size())
                                    {
                                        const float oldSpan = old[i + 1] - old[i];
                                        const float newSpan = replacement[i + 1] - replacement[i];
                                        if (oldSpan > 0.000001f && newSpan > 0.000001f)
                                            for (float &component : shape.tangentsOut[i])
                                                component *= oldSpan / newSpan;
                                    }
                                }
                            }
                            shape.parameters = std::move(replacement);
                        };
                        if (ImGui::Button("Reparameterize by distance") && !shape.points.empty())
                        {
                            std::vector<float> replacement(shape.points.size(), 0.0f);
                            for (std::size_t i = 1; i < shape.points.size(); ++i)
                            {
                                const glm::vec3 a(shape.points[i - 1][0], shape.points[i - 1][1],
                                                  shape.points[i - 1][2]);
                                const glm::vec3 b(shape.points[i][0], shape.points[i][1], shape.points[i][2]);
                                replacement[i] = replacement[i - 1] + glm::length(b - a);
                            }
                            replaceParametersPreservingCurve(std::move(replacement));
                            status =
                                "Reparameterized SHAPE by chord distance and rescaled cubic derivatives to preserve its curve.";
                        }
                        ImGui::SameLine();
                        if (ImGui::Button("Uniform parameters") && !shape.parameters.empty())
                        {
                            std::vector<float> replacement(shape.parameters.size());
                            for (std::size_t i = 0; i < replacement.size(); ++i)
                                replacement[i] = static_cast<float>(i);
                            replaceParametersPreservingCurve(std::move(replacement));
                            status = "Assigned uniform SHAPE parameters without changing the cubic path.";
                        }
                        if (ImGui::Button("Normalize parameters") && shape.parameters.size() > 1)
                        {
                            const float first = shape.parameters.front();
                            const float range = shape.parameters.back() - first;
                            if (range > 0.000001f)
                            {
                                auto replacement = shape.parameters;
                                for (auto &parameter : replacement)
                                    parameter = (parameter - first) / range;
                                replaceParametersPreservingCurve(std::move(replacement));
                            }
                            status = range > 0.000001f ? "Normalized the SHAPE parameter range to 0..1."
                                                       : "Cannot normalize a zero-length parameter range.";
                        }
                        ImGui::SameLine();
                        if (ImGui::Button("Reverse direction"))
                        {
                            const float parameterMin = shape.parameters.empty() ? 0.0f : shape.parameters.front();
                            const float parameterMax = shape.parameters.empty() ? 0.0f : shape.parameters.back();
                            std::reverse(shape.points.begin(), shape.points.end());
                            std::reverse(shape.parameters.begin(), shape.parameters.end());
                            for (auto &parameter : shape.parameters)
                                parameter = parameterMin + parameterMax - parameter;
                            if (shape.hermite)
                            {
                                std::reverse(shape.tangentsIn.begin(), shape.tangentsIn.end());
                                std::reverse(shape.tangentsOut.begin(), shape.tangentsOut.end());
                                for (std::size_t i = 0; i < shape.tangentsIn.size(); ++i)
                                {
                                    std::swap(shape.tangentsIn[i], shape.tangentsOut[i]);
                                    for (int axis = 0; axis < 3; ++axis)
                                    {
                                        shape.tangentsIn[i][axis] = -shape.tangentsIn[i][axis];
                                        shape.tangentsOut[i][axis] = -shape.tangentsOut[i][axis];
                                    }
                                }
                            }
                            selectedShapePoint = static_cast<int>(shape.points.size()) - 1 - selectedShapePoint;
                            status = "Reversed SHAPE traversal direction.";
                        }
                        ImGui::BeginDisabled(shape.points.size() >= 255 || shape.closed);
                        if (ImGui::Button("Add control point"))
                        {
                            auto point = shape.points.empty() ? std::array<float, 3>{} : shape.points.back();
                            if (shape.points.size() > 1)
                                for (int axis = 0; axis < 3; ++axis)
                                    point[axis] +=
                                        shape.points.back()[axis] - shape.points[shape.points.size() - 2][axis];
                            shape.points.push_back(point);
                            shape.parameters.push_back(shape.parameters.empty() ? 0.0f
                                                                                : shape.parameters.back() + 1.0f);
                            if (shape.hermite)
                            {
                                shape.tangentsIn.push_back({});
                                shape.tangentsOut.push_back({});
                            }
                            selectedShapePoint = static_cast<int>(shape.points.size() - 1);
                            status = "Added a SHAPE control point.";
                        }
                        ImGui::EndDisabled();
                        if (shape.closed && ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
                            ImGui::SetTooltip(
                                "Closed SHAPEs reserve the final point as the explicit seam. Select a point and use Insert after.");
                        ImGui::SameLine();
                        if (ImGui::Button("Insert after") && !shape.points.empty() && shape.points.size() < 255)
                        {
                            const std::size_t current = static_cast<std::size_t>(
                                std::clamp(selectedShapePoint, 0, static_cast<int>(shape.points.size()) - 1));
                            const std::size_t next = current + 1 < shape.points.size() ? current + 1 : current;
                            std::array<float, 3> point = shape.points[current];
                            for (int axis = 0; axis < 3; ++axis)
                                point[axis] = current == next ? point[axis] + (axis == 0 ? 100.0f : 0.0f)
                                                              : (point[axis] + shape.points[next][axis]) * 0.5f;
                            const float parameter = current == next
                                                        ? shape.parameters[current] + 1.0f
                                                        : (shape.parameters[current] + shape.parameters[next]) * 0.5f;
                            shape.points.insert(shape.points.begin() + static_cast<std::ptrdiff_t>(current + 1), point);
                            shape.parameters.insert(shape.parameters.begin() + static_cast<std::ptrdiff_t>(current + 1),
                                                    parameter);
                            if (shape.hermite)
                            {
                                shape.tangentsIn.insert(
                                    shape.tangentsIn.begin() + static_cast<std::ptrdiff_t>(current + 1), {});
                                shape.tangentsOut.insert(
                                    shape.tangentsOut.begin() + static_cast<std::ptrdiff_t>(current + 1), {});
                            }
                            selectedShapePoint = static_cast<int>(current + 1);
                            status = "Inserted a SHAPE control point.";
                        }
                        ImGui::SameLine();
                        ImGui::BeginDisabled(shape.points.size() <= (shape.closed ? 3u : 2u));
                        if (ImGui::Button("Delete selected point"))
                        {
                            const std::size_t remove = static_cast<std::size_t>(
                                std::clamp(selectedShapePoint, 0, static_cast<int>(shape.points.size()) - 1));
                            shape.points.erase(shape.points.begin() + static_cast<std::ptrdiff_t>(remove));
                            shape.parameters.erase(shape.parameters.begin() + static_cast<std::ptrdiff_t>(remove));
                            if (shape.hermite)
                            {
                                shape.tangentsIn.erase(shape.tangentsIn.begin() + static_cast<std::ptrdiff_t>(remove));
                                shape.tangentsOut.erase(shape.tangentsOut.begin() +
                                                        static_cast<std::ptrdiff_t>(remove));
                            }
                            if (shape.closed && shape.points.size() >= 2)
                            {
                                shape.points.back() = shape.points.front();
                                if (shape.hermite && shape.tangentsIn.size() == shape.points.size() &&
                                    shape.tangentsOut.size() == shape.points.size())
                                {
                                    shape.tangentsIn.back() = shape.tangentsOut.front();
                                    shape.tangentsOut.back() = shape.tangentsOut.front();
                                }
                            }
                            selectedShapePoint =
                                std::min(selectedShapePoint, static_cast<int>(shape.points.size()) - 1);
                            status = "Deleted the selected SHAPE control point.";
                        }
                        ImGui::EndDisabled();
                        if (!shape.points.empty())
                        {
                            const int editableLast = shape.closed && shape.points.size() > 1
                                                         ? static_cast<int>(shape.points.size()) - 2
                                                         : static_cast<int>(shape.points.size()) - 1;
                            selectedShapePoint = std::clamp(selectedShapePoint, 0, (std::max)(editableLast, 0));
                            ImGui::SliderInt("Selected control point", &selectedShapePoint, 0,
                                             (std::max)(editableLast, 0));
                            if (shape.closed)
                                ImGui::TextDisabled(
                                    "Point %zu is the authored seam copy and is edited through point 0.",
                                    shape.points.size() - 1);
                            ImGui::InputFloat("Curve parameter",
                                              &shape.parameters[static_cast<std::size_t>(selectedShapePoint)]);
                            ImGui::DragFloat3("Local position",
                                              shape.points[static_cast<std::size_t>(selectedShapePoint)].data(), 1.0f);
                            ImGui::SetNextItemWidth(120.0f);
                            ImGui::DragFloat("Snap grid", &shapeSnapGrid, 1.0f, 0.0f, 10000.0f, "%.1f");
                            ImGui::SameLine();
                            if (ImGui::Button("Snap point") && shapeSnapGrid > 0.0f)
                            {
                                auto &point = shape.points[static_cast<std::size_t>(selectedShapePoint)];
                                for (float &coordinate : point)
                                    coordinate = std::round(coordinate / shapeSnapGrid) * shapeSnapGrid;
                                status = "Snapped the selected SHAPE point to its parent-local grid.";
                            }
                            if (shape.hermite && shape.tangentsIn.size() == shape.points.size())
                            {
                                const char *handleModes[]{"Free", "Aligned", "Mirrored", "Automatic"};
                                ImGui::Combo("Handle mode", &shapeHandleMode, handleModes, 4);
                                ImGui::DragFloat3("Incoming handle",
                                                  shape.tangentsIn[static_cast<std::size_t>(selectedShapePoint)].data(),
                                                  1.0f);
                                ImGui::DragFloat3(
                                    "Outgoing handle",
                                    shape.tangentsOut[static_cast<std::size_t>(selectedShapePoint)].data(), 1.0f);
                                if (shapeHandleMode == 2)
                                    for (int axis = 0; axis < 3; ++axis)
                                        shape.tangentsIn[static_cast<std::size_t>(selectedShapePoint)][axis] =
                                            shape.tangentsOut[static_cast<std::size_t>(selectedShapePoint)][axis];
                                else if (shapeHandleMode == 1)
                                {
                                    auto &incoming = shape.tangentsIn[static_cast<std::size_t>(selectedShapePoint)];
                                    const auto &outgoing =
                                        shape.tangentsOut[static_cast<std::size_t>(selectedShapePoint)];
                                    const glm::vec3 out(outgoing[0], outgoing[1], outgoing[2]);
                                    const glm::vec3 in(incoming[0], incoming[1], incoming[2]);
                                    if (glm::length(out) > 0.0001f)
                                    {
                                        const glm::vec3 aligned = glm::normalize(out) * glm::length(in);
                                        incoming = {aligned.x, aligned.y, aligned.z};
                                    }
                                }
                                else if (shapeHandleMode == 3 && shape.points.size() > 1)
                                {
                                    const std::size_t pointIndex = static_cast<std::size_t>(selectedShapePoint);
                                    const std::size_t previous =
                                        pointIndex > 0
                                            ? pointIndex - 1
                                            : (shape.closed && shape.points.size() > 2 ? shape.points.size() - 2
                                                                                       : pointIndex);
                                    const std::size_t next = pointIndex + 1 < shape.points.size()
                                                                 ? pointIndex + 1
                                                                 : (shape.closed ? 0 : pointIndex);
                                    const glm::vec3 before(shape.points[previous][0], shape.points[previous][1],
                                                           shape.points[previous][2]);
                                    const glm::vec3 after(shape.points[next][0], shape.points[next][1],
                                                          shape.points[next][2]);
                                    float parameterSpan =
                                        previous < shape.parameters.size() && next < shape.parameters.size()
                                            ? std::abs(shape.parameters[next] - shape.parameters[previous])
                                            : 0.0f;
                                    if (shape.closed && pointIndex == 0 && shape.parameters.size() > 2)
                                        parameterSpan =
                                            (shape.parameters.back() - shape.parameters[shape.parameters.size() - 2]) +
                                            (shape.parameters[1] - shape.parameters.front());
                                    const glm::vec3 derivative =
                                        parameterSpan > 0.000001f ? (after - before) / parameterSpan : glm::vec3(0.0f);
                                    shape.tangentsIn[pointIndex] = {derivative.x, derivative.y, derivative.z};
                                    shape.tangentsOut[pointIndex] = {derivative.x, derivative.y, derivative.z};
                                }
                            }
                            glm::mat4 pathToWorld(1.0f);
                            if (object.parentIndex >= 0 &&
                                static_cast<std::size_t>(object.parentIndex) < document.Objects().size())
                                pathToWorld = sceneRenderer.ResolvedObjectTransform(object.parentIndex);
                            const auto &local = shape.points[static_cast<std::size_t>(selectedShapePoint)];
                            const glm::vec3 worldPoint =
                                glm::vec3(pathToWorld * glm::vec4(local[0], local[1], local[2], 1.0f));
                            ImGui::TextDisabled("World position: %.2f, %.2f, %.2f", worldPoint.x, worldPoint.y,
                                                worldPoint.z);
                            ImGui::SameLine();
                            if (ImGui::SmallButton("Frame point"))
                                camera.FocusPoint(worldPoint, 250.0f);
                            ImGui::SameLine();
                            if (ImGui::SmallButton("Drop to surface"))
                            {
                                const glm::vec3 rayOrigin = worldPoint + glm::vec3(0.0f, 0.0f, 1.0f);
                                const glm::vec3 rayDirection(0.0f, 0.0f, -1.0f);
                                float closest = std::numeric_limits<float>::max();
                                glm::vec3 surface{};
                                for (const auto &triangle : document.CollisionTriangles())
                                {
                                    if (triangle.cameraGeometry)
                                        continue;
                                    const glm::vec3 a(triangle.positions[0][0], triangle.positions[0][1],
                                                      triangle.positions[0][2]);
                                    const glm::vec3 b(triangle.positions[1][0], triangle.positions[1][1],
                                                      triangle.positions[1][2]);
                                    const glm::vec3 c(triangle.positions[2][0], triangle.positions[2][1],
                                                      triangle.positions[2][2]);
                                    const glm::vec3 edge1 = b - a, edge2 = c - a;
                                    const glm::vec3 p = glm::cross(rayDirection, edge2);
                                    const float determinant = glm::dot(edge1, p);
                                    if (std::abs(determinant) <= 0.000001f)
                                        continue;
                                    const float inverse = 1.0f / determinant;
                                    const glm::vec3 offset = rayOrigin - a;
                                    const float u = glm::dot(offset, p) * inverse;
                                    if (u < 0.0f || u > 1.0f)
                                        continue;
                                    const glm::vec3 q = glm::cross(offset, edge1);
                                    const float v = glm::dot(rayDirection, q) * inverse;
                                    if (v < 0.0f || u + v > 1.0f)
                                        continue;
                                    const float distance = glm::dot(edge2, q) * inverse;
                                    if (distance >= 0.0f && distance < closest)
                                    {
                                        closest = distance;
                                        surface = rayOrigin + rayDirection * distance;
                                    }
                                }
                                if (closest < std::numeric_limits<float>::max())
                                {
                                    const glm::vec3 localSurface =
                                        glm::vec3(glm::inverse(pathToWorld) * glm::vec4(surface, 1.0f));
                                    auto &point = shape.points[static_cast<std::size_t>(selectedShapePoint)];
                                    point = {localSurface.x, localSurface.y, localSurface.z};
                                    status = "Dropped the selected SHAPE point onto gameplay collision.";
                                }
                                else
                                    status = "No gameplay collision was found below this SHAPE point.";
                            }
                            ImGui::SeparatorText("Control points");
                            if (ImGui::BeginChild("ShapePointList", ImVec2(0.0f, 150.0f), true))
                            {
                                for (std::size_t pointIndex = 0; pointIndex < shape.points.size(); ++pointIndex)
                                {
                                    const float parameter =
                                        pointIndex < shape.parameters.size() ? shape.parameters[pointIndex] : 0.0f;
                                    char label[96];
                                    const bool seamPoint = shape.closed && pointIndex + 1 == shape.points.size();
                                    std::snprintf(label, sizeof(label),
                                                  seamPoint ? "Point %zu   u=%.3f   [seam copy]" : "Point %zu   u=%.3f",
                                                  pointIndex, parameter);
                                    ImGui::BeginDisabled(seamPoint);
                                    if (ImGui::Selectable(label, selectedShapePoint == static_cast<int>(pointIndex)) &&
                                        !seamPoint)
                                        selectedShapePoint = static_cast<int>(pointIndex);
                                    ImGui::EndDisabled();
                                }
                            }
                            ImGui::EndChild();
                        }
                        if (shape.closed && shape.points.size() > 1)
                        {
                            const glm::vec3 first(shape.points.front()[0], shape.points.front()[1],
                                                  shape.points.front()[2]);
                            const glm::vec3 last(shape.points.back()[0], shape.points.back()[1],
                                                 shape.points.back()[2]);
                            bool derivativeMismatch = false;
                            if (shape.hermite && shape.tangentsIn.size() == shape.points.size() &&
                                shape.tangentsOut.size() == shape.points.size())
                            {
                                const glm::vec3 endDerivative(shape.tangentsIn.back()[0], shape.tangentsIn.back()[1],
                                                              shape.tangentsIn.back()[2]);
                                const glm::vec3 startDerivative(shape.tangentsOut.front()[0],
                                                                shape.tangentsOut.front()[1],
                                                                shape.tangentsOut.front()[2]);
                                derivativeMismatch = glm::distance(endDerivative, startDerivative) > 0.01f;
                            }
                            if (glm::distance(first, last) > 0.01f || derivativeMismatch)
                            {
                                ImGui::TextColored(
                                    ImVec4(1.0f, 0.4f, 0.2f, 1.0f),
                                    "Closed seam position or derivative is discontinuous at wraparound.");
                                if (ImGui::Button("Repair closed seam"))
                                {
                                    shape.points.back() = shape.points.front();
                                    if (shape.hermite && shape.tangentsIn.size() == shape.points.size() &&
                                        shape.tangentsOut.size() == shape.points.size())
                                    {
                                        shape.tangentsIn.back() = shape.tangentsOut.front();
                                        shape.tangentsOut.back() = shape.tangentsOut.front();
                                    }
                                    status =
                                        "Repaired the explicit SHAPE seam and matched its runtime endpoint derivative.";
                                }
                            }
                        }
                        ImGui::EndDisabled();
                        ImGui::EndDisabled();
                        ImGui::SeparatorText("Traversal preview");
                        ImGui::SliderFloat("Path progress", &shapePreviewParameter, 0.0f, 1.0f, "%.3f");
                        if (ImGui::Button(shapePreviewPlaying ? "Pause" : "Play"))
                            shapePreviewPlaying = !shapePreviewPlaying;
                        ImGui::SameLine();
                        if (ImGui::Button("Restart"))
                        {
                            shapePreviewParameter = 0.0f;
                            shapePreviewPlaying = true;
                        }
                        ImGui::SameLine();
                        ImGui::Checkbox("Loop", &shapePreviewLoop);
                        ImGui::SliderFloat("Preview speed", &shapePreviewSpeed, 0.01f, 2.0f, "%.2f path/s");
                        float measuredLength = 0.0f;
                        for (std::size_t i = 1; i < shape.points.size(); ++i)
                        {
                            const glm::vec3 p0(shape.points[i - 1][0], shape.points[i - 1][1], shape.points[i - 1][2]);
                            const glm::vec3 p3(shape.points[i][0], shape.points[i][1], shape.points[i][2]);
                            if (!shape.hermite || shape.tangentsIn.size() != shape.points.size() ||
                                shape.tangentsOut.size() != shape.points.size())
                            {
                                measuredLength += glm::distance(p0, p3);
                                continue;
                            }
                            const float du = shape.parameters[i] - shape.parameters[i - 1];
                            const glm::vec3 p1 =
                                p0 + glm::vec3(shape.tangentsOut[i - 1][0], shape.tangentsOut[i - 1][1],
                                               shape.tangentsOut[i - 1][2]) *
                                         (du / 3.0f);
                            const glm::vec3 p2 =
                                p3 - glm::vec3(shape.tangentsIn[i][0], shape.tangentsIn[i][1], shape.tangentsIn[i][2]) *
                                         (du / 3.0f);
                            glm::vec3 previous = p0;
                            // Retail SBezierPosLength uses 20 tessellated positions.
                            for (int sample = 1; sample < 20; ++sample)
                            {
                                const float t = static_cast<float>(sample) / 19.0f, u = 1.0f - t;
                                const glm::vec3 current =
                                    u * u * u * p0 + 3.0f * u * u * t * p1 + 3.0f * u * t * t * p2 + t * t * t * p3;
                                measuredLength += glm::distance(previous, current);
                                previous = current;
                            }
                        }
