                        root.planeDistance = camera.Position().x;
                        root.negativeChild = root.positiveChild = -1;
                        root.negativeZoneMask = root.positiveZoneMask = 1u;
                        nodes.push_back(root);
                        selectedVisibilityNode = 0;
                        auto &header = document.EditableWorldHeader();
                        if (header.visibilityZoneCount == 0)
                            header.visibilityZoneCount = 1;
                        if (oneHopMasks.empty())
                            oneHopMasks.push_back(1u);
